var fs = require('fs')
var resolve = require('./resolve.js')
var HtmlWebpackPlugin = require('html-webpack-plugin')


var entrydir = fs.readdirSync(resolve('src/entry'))
var templatedir = fs.readdirSync(resolve('src/html'))

var entry = {}
entrydir.forEach(function (value,index) {
	entry[value.split('.')[0]] = resolve('src/entry/'+value)
})

var html = []
Object.keys(entry).forEach(function (value) {
	html.push(new HtmlWebpackPlugin({
	  filename: value === 'index'
	  			? value + '.html'
	  			: ('html/'+value) +'.html',
	  template: templatedir.indexOf(value+'.html') === -1
	  			?resolve('index.html')
	  			:resolve('src/html/'+value+'.html'),
	  chunks: [value],
	  inject: true,
	  chunksSortMode: 'dependency',
	}))
})

var buildhtml = []
Object.keys(entry).forEach(function (value) {
  buildhtml.push(new HtmlWebpackPlugin({
    filename: value === 'index'
          ? value + '.html'
          : ('html/'+value) +'.html',
    template: templatedir.indexOf(value+'.html') === -1
          ?resolve('index.html')
          :resolve('src/html/'+value+'.html'),
    chunks: [value,'commons'],
    inject: true,
    chunksSortMode: 'dependency',
  }))
})

var rewrites = []
Object.keys(entry).forEach(function (value) {
  if (value === 'index') {
    return
  }
  rewrites.push({
    from: new RegExp('^\/'+value+'$'),
    to: '/html/'+ value + '.html',
  })
})

module.exports = {
	html,
	entry,
	rewrites,
  buildhtml
}

